\",\n    },\n  }\n)\n\nfunction Button({\n  className,\n  variant,\n  size,\n  asChild = false,\n  ...props\n}: React.ComponentProps<\"button\"> &\n  VariantProps<typeof buttonVariants> & {\n    asChild?: boolean\n  }) {\n  const Comp = asChild ? Slot : \"button\"\n\n  return (\n    <Comp\n      data-slot=\"button\"\n      className={cn(buttonVariants({ variant, size, className }))}\n      {...props}\n    />\n  )\n}\n\nexport { Button, buttonVariants }\n"],"names":[],"mappings":";;;;;;;AACA;AACA;AAEA;;;;;AAEA,MAAM,iBAAiB,IAAA,0KAAG,EACxB,+bACA;IACE,UAAU;QACR,SAAS;YACP,SAAS;YACT,aACE;YACF,SACE;YACF,WACE;YACF,OACE;YACF,MAAM;QACR;QACA,MAAM;YACJ,SAAS;YACT,IAAI;YACJ,IAAI;YACJ,MAAM;YACN,WAAW;YACX,WAAW;QACb;IACF;IACA,iBAAiB;QACf,SAAS;QACT,MAAM;IACR;AACF;AAGF,SAAS,OAAO,KASb;QATa,EACd,SAAS,EACT,OAAO,EACP,IAAI,EACJ,UAAU,KAAK,EACf,GAAG,OAIF,GATa;IAUd,MAAM,OAAO,UAAU,2KAAI,GAAG;IAE9B,qBACE,6LAAC;QACC,aAAU;QACV,WAAW,IAAA,4HAAE,EAAC,eAAe;YAAE;YAAS;YAAM;QAAU;QACvD,GAAG,KAAK;;;;;;AAGf;KAnBS","debugId":null}},
    {"offset": {"line": 91, "column": 0}, "map": {"version":3,"sources":["file:///home/minhajul-abedin/Documents/Projects/terranwilliams/workforce_kreatovate/src/app/error.tsx"],"sourcesContent":["\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { Button } from \"@/components/ui/button\";\nimport { cn } from \"@/lib/utils\";\nimport { AlertTriangle, RefreshCcw } from \"lucide-react\";\n\nexport default function Error({\n  error,\n  reset,\n}: {\n  error: Error & { digest?: string };\n  reset: () => void;\n}) {\n  const [isSpinning, setIsSpinning] = useState(false);\n\n  useEffect(() => {\n    console.error(error);\n  }, [error]);\n\n  const handleTryAgain = () => {\n    setIsSpinning(true);\n    // wait a short moment before resetting\n    setTimeout(() => {\n      setIsSpinning(false);\n      reset();\n    }, 1200);\n  };\n\n  return (\n    <main className=\"relative min-h-screen bg-[#000] text-foreground overflow-hidden font-jakarta flex items-center justify-center px-6 py-20\">\n      {/* background gradient mesh */}\n      <div\n        aria-hidden\n        className=\"pointer-events-none absolute inset-0 [background:radial-gradient(60%_40%_at_20%_0%,rgba(233,61,61,0.25),transparent_60%),radial-gradient(50%_40%_at_80%_0%,rgba(78,48,254,0.25),transparent_60%),radial-gradient(40%_50%_at_50%_100%,rgba(255,255,255,0.06),transparent_60%)]\"\n      />\n\n      {/* main card */}\n      <section className=\"relative z-10 w-full max-w-xl text-center\">\n        <div className=\"rounded-[20px] border border-white/20 bg-white/5 backdrop-blur-xl p-8 md:p-10 shadow-[0_10px_40px_rgba(78,48,254,0.15)]\">\n          {/* badge and icon */}\n          <div className=\"flex flex-col items-center gap-3 mb-4\">\n            <div className=\"inline-flex items-center gap-2 rounded-full border border-white/25 bg-white/10 px-3 py-1 text-xs uppercase tracking-wider\">\n              <span className=\"h-2 w-2 rounded-full bg-[#E93D3D]\" />\n              Unexpected Error\n            </div>\n            <AlertTriangle className=\"h-12 w-12 text-[#E93D3D]\" />\n          </div>\n\n          {/* title */}\n          <h1\n            className={cn(\n              \"block text-4xl sm:text-5xl font-extrabold leading-tight mb-3\",\n              \"text-gradient\"\n            )}\n          >\n            Something went wrong!\n          </h1>\n\n          <p className=\"text-white/80 leading-relaxed mb-8 max-w-md mx-auto\">\n            We’re experiencing a temporary issue. You can refresh the page or go\n            back to the homepage while we work on a fix.\n          </p>\n\n          {/* actions */}\n          <div className=\"flex flex-col sm:flex-row items-center justify-center gap-3\">\n            <Button\n              onClick={handleTryAgain}\n              size=\"lg\"\n              disabled={isSpinning}\n              className={cn(\n                \"rounded-[12px] border border-white px-6 h-12 text-white text-[18px] font-medium leading-[180%]\",\n                \"btn-gradient hover:scale-[1.02] hover:shadow-[0_0_20px_rgba(255,0,255,0.2)] cursor-pointer\"\n              )}\n            >\n              <RefreshCcw\n                className={cn(\n                  \"mr-2 h-4 w-4 transition-transform duration-700\",\n                  isSpinning && \"animate-spin\"\n                )}\n              />\n              {isSpinning ? \"Trying...\" : \"Try Again\"}\n            </Button>\n\n            <Button\n              asChild\n              size=\"lg\"\n              variant=\"outline\"\n              className={cn(\n                \"rounded-[12px] h-12 px-6 text-white border-white/40 bg-white/5 hover:bg-white/10 hover:text-white cursor-pointer\"\n              )}\n            >\n              <Link href=\"/\">Back to Home</Link>\n            </Button>\n          </div>\n        </div>\n      </section>\n\n      {/* soft glows */}\n      <div\n        aria-hidden\n        className=\"absolute -left-24 top-1/3 h-64 w-64 rounded-full blur-3xl opacity-30 bg-[radial-gradient(circle,rgba(233,61,61,0.6),transparent_60%)]\"\n      />\n      <div\n        aria-hidden\n        className=\"absolute -right-24 bottom-1/4 h-64 w-64 rounded-full blur-3xl opacity-30 bg-[radial-gradient(circle,rgba(78,48,254,0.6),transparent_60%)]\"\n      />\n    </main>\n  );\n}\n"],"names":[],"mappings":";;;;;AAEA;AACA;AACA;AACA;AACA;AAAA;;;AANA;;;;;;AAQe,SAAS,MAAM,KAM7B;QAN6B,EAC5B,KAAK,EACL,KAAK,EAIN,GAN6B;;IAO5B,MAAM,CAAC,YAAY,cAAc,GAAG,IAAA,yKAAQ,EAAC;IAE7C,IAAA,0KAAS;2BAAC;YACR,QAAQ,KAAK,CAAC;QAChB;0BAAG;QAAC;KAAM;IAEV,MAAM,iBAAiB;QACrB,cAAc;QACd,uCAAuC;QACvC,WAAW;YACT,cAAc;YACd;QACF,GAAG;IACL;IAEA,qBACE,6LAAC;QAAK,WAAU;;0BAEd,6LAAC;gBACC,aAAW;gBACX,WAAU;;;;;;0BAIZ,6LAAC;gBAAQ,WAAU;0BACjB,cAAA,6LAAC;oBAAI,WAAU;;sCAEb,6LAAC;4BAAI,WAAU;;8CACb,6LAAC;oCAAI,WAAU;;sDACb,6LAAC;4CAAK,WAAU;;;;;;wCAAsC;;;;;;;8CAGxD,6LAAC,4OAAa;oCAAC,WAAU;;;;;;;;;;;;sCAI3B,6LAAC;4BACC,WAAW,IAAA,4HAAE,EACX,gEACA;sCAEH;;;;;;sCAID,6LAAC;4BAAE,WAAU;sCAAsD;;;;;;sCAMnE,6LAAC;4BAAI,WAAU;;8CACb,6LAAC,+IAAM;oCACL,SAAS;oCACT,MAAK;oCACL,UAAU;oCACV,WAAW,IAAA,4HAAE,EACX,kGACA;;sDAGF,6LAAC,mOAAU;4CACT,WAAW,IAAA,4HAAE,EACX,kDACA,cAAc;;;;;;wCAGjB,aAAa,cAAc;;;;;;;8CAG9B,6LAAC,+IAAM;oCACL,OAAO;oCACP,MAAK;oCACL,SAAQ;oCACR,WAAW,IAAA,4HAAE,EACX;8CAGF,cAAA,6LAAC,0KAAI;wCAAC,MAAK;kDAAI;;;;;;;;;;;;;;;;;;;;;;;;;;;;0BAOvB,6LAAC;gBACC,aAAW;gBACX,WAAU;;;;;;0BAEZ,6LAAC;gBACC,aAAW;gBACX,WAAU;;;;;;;;;;;;AAIlB;GAtGwB;KAAA","debugId":null}}]
